/* ---------- 🚀 PUBLICATION DE LA VERSION LÉGÈRE (lecture seule) SUR GITHUB ----------
   Part de buildHTML(true) (export lecture seule), le découpe en dossier léger
   (images WebP, applis et cours chargés à la demande, PWA hors ligne) puis l'envoie
   sur GitHub par l'API : seuls les fichiers modifiés sont envoyés.
   Le jeton GitHub reste dans ce navigateur (localStorage), jamais dans le fichier. */
const PUBK=APPID+'_pub_v1',PUBC=APPID+'_pubcache_v1';
function pubCfg(){try{return JSON.parse(localStorage.getItem(PUBK)||'{}')||{}}catch(e){return{}}}
function pubSet(c){try{localStorage.setItem(PUBK,JSON.stringify(c))}catch(e){}}
function pubCache(){try{return JSON.parse(localStorage.getItem(PUBC)||'{}')||{}}catch(e){return{}}}
const PENC=new TextEncoder();
function sha1js(u){const w=new Uint32Array(80),l=u.length,n=((l+8>>6)+1)*16,m=new Uint32Array(n);for(let i=0;i<l;i++)m[i>>2]|=u[i]<<(24-(i%4)*8);m[l>>2]|=0x80<<(24-(l%4)*8);m[n-1]=l*8;let a=0x67452301,b=0xEFCDAB89,c=0x98BADCFE,d=0x10325476,e=0xC3D2E1F0;const r=(x,k)=>x<<k|x>>>32-k;
 for(let i=0;i<n;i+=16){let A=a,B=b,C=c,D=d,E5=e;for(let j=0;j<80;j++){w[j]=j<16?m[i+j]:r(w[j-3]^w[j-8]^w[j-14]^w[j-16],1);const f=j<20?(B&C|~B&D)+0x5A827999:j<40?(B^C^D)+0x6ED9EBA1:j<60?(B&C|B&D|C&D)+0x8F1BBCDC:(B^C^D)+0xCA62C1D6;const t=r(A,5)+f+E5+w[j]|0;E5=D;D=C;C=r(B,30);B=A;A=t}a=a+A|0;b=b+B|0;c=c+C|0;d=d+D|0;e=e+E5|0}
 return[a,b,c,d,e].map(x=>(x>>>0).toString(16).padStart(8,'0')).join('')}
async function psha1(u){try{if(crypto&&crypto.subtle){const h=await crypto.subtle.digest('SHA-1',u);return[...new Uint8Array(h)].map(x=>x.toString(16).padStart(2,'0')).join('')}}catch(e){}return sha1js(u)}
async function gitSha(u){const h=PENC.encode('blob '+u.length+'\0'),a=new Uint8Array(h.length+u.length);a.set(h);a.set(u,h.length);return psha1(a)}
function b64u(b){const s=atob(b),u=new Uint8Array(s.length);for(let i=0;i<s.length;i++)u[i]=s.charCodeAt(i);return u}
function u64(u){let s='';for(let i=0;i<u.length;i+=0x8000)s+=String.fromCharCode.apply(null,u.subarray(i,i+0x8000));return btoa(s)}
async function toWebp(u,mime){try{const bm=await createImageBitmap(new Blob([u],{type:mime}));const c=document.createElement('canvas');c.width=bm.width;c.height=bm.height;c.getContext('2d').drawImage(bm,0,0);
 const bl=await new Promise(ok=>c.toBlob(ok,'image/webp',.72));if(bl&&bl.type==='image/webp'&&bl.size<u.length)return{b:new Uint8Array(await bl.arrayBuffer()),ext:'webp'}}catch(e){}
 return{b:u,ext:/png/.test(mime)?'png':/gif/.test(mime)?'gif':'jpg'}}
const ICON_SRC='data:image/webp;base64,';
async function pubIcons(){const im=await createImageBitmap(new Blob([b64u(ICON_SRC.split(',')[1])],{type:'image/webp'}));
 const mk=async(sz,sc,bg)=>{const c=document.createElement('canvas');c.width=c.height=sz;const x=c.getContext('2d');x.imageSmoothingQuality='high';if(bg){x.fillStyle=bg;x.fillRect(0,0,sz,sz)}const k=Math.round(sz*sc);x.drawImage(im,(sz-k)/2,(sz-k)/2,k,k);const bl=await new Promise(ok=>c.toBlob(ok,'image/png'));return new Uint8Array(await bl.arrayBuffer())};
 return{'icons/icon-192.png':await mk(192,1),'icons/icon-512.png':await mk(512,1),'icons/icon-maskable-512.png':await mk(512,.84,'#083416'),'icons/apple-touch-icon.png':await mk(180,.94,'#083416')}}

/* remplace dans les réglages (E) chaque image intégrée (data:image…) par un fichier img/e-<empreinte>.<ext> */
async function edImgOut(o,save){const walk=async(v)=>{if(typeof v==='string'){const m=/^data:image\/(webp|jpeg|jpg|png|gif);base64,/.exec(v);if(!m||v.length<1500)return v;let b;try{b=atob(v.slice(m[0].length))}catch(e){return v}const u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);
  const h=[...new Uint8Array(await crypto.subtle.digest('SHA-1',u))].map(x=>x.toString(16).padStart(2,'0')).join('').slice(0,12);const path='img/e-'+h+'.'+(m[1]==='jpeg'?'jpg':m[1]);await save(path,u);return path}
 if(Array.isArray(v)){for(let i=0;i<v.length;i++)v[i]=await walk(v[i]);return v}if(v&&typeof v==='object'){for(const k of Object.keys(v))v[k]=await walk(v[k]);return v}return v};return walk(o)}
const PMANAGED=p=>/^(img|apps|data|icons)\//.test(p)||['index.html','data.js','sw.js','manifest.json','.nojekyll','version.json'].includes(p);

