async function gh(cfg,method,path,body){let r;try{r=await fetch('https://api.github.com/repos/'+cfg.repo+path,{method,headers:{'Authorization':'Bearer '+cfg.token,'Accept':'application/vnd.github+json'},body:body?JSON.stringify(body):undefined})}catch(e){throw new Error('Pas de connexion à GitHub')}
 const j=await r.json().catch(()=>({}));if(!r.ok){const er=new Error(r.status===401?'Jeton GitHub invalide ou expiré':r.status===404?'Dépôt introuvable, ou le jeton n’a pas accès à ce dépôt':r.status===403?'Le jeton n’a pas le droit d’écrire (permission « Contents : Read and write »)':(j.message||'Erreur GitHub')+' ('+r.status+')');er.status=r.status;throw er}return j}
async function pool(items,n,fn){let i=0;await Promise.all(Array.from({length:Math.min(n,items.length)},async()=>{while(i<items.length){const x=items[i++];await fn(x)}}))}
async function publishGH(cfg,log){
 const br=encodeURIComponent(cfg.branch||'main');let head=null,remote={};
 log('Connexion à GitHub…');
 try{head=(await gh(cfg,'GET','/git/ref/heads/'+br)).object.sha}catch(e){if(e.status!==404&&e.status!==409)throw e}
 if(!head){log('Dépôt vide : initialisation…');await gh(cfg,'PUT','/contents/README.md',{message:'Initialisation',content:u64(PENC.encode('# Révision INFAS\n')),branch:cfg.branch||'main'});head=(await gh(cfg,'GET','/git/ref/heads/'+br)).object.sha}
 const hc=await gh(cfg,'GET','/git/commits/'+head);const tr=await gh(cfg,'GET','/git/trees/'+hc.tree.sha+'?recursive=1');
 (tr.tree||[]).forEach(x=>{if(x.type==='blob')remote[x.path]=x});
 const cache=pubCache();const reuse=key=>{const c=cache[key];return c&&remote[c.p]&&remote[c.p].sha===c.s?c:null};
 let prev=null;if(remote['version.json']){try{const bl=await gh(cfg,'GET','/git/blobs/'+remote['version.json'].sha);prev=JSON.parse(new TextDecoder().decode(b64u((bl.content||'').replace(/\s/g,''))))}catch(e){prev=null}}
 const _vl=stVersionEnLigne(remote['version.json']?prev:undefined);if(_vl.erreur)throw new Error('Publication arrêtée : '+_vl.erreur);
 const{F,keys,rel}=await buildLight(log,reuse,prev,cfg.msg);
 stPublicationN3(F,remote,_vl);
 const up=Object.keys(F).filter(p=>F[p].b&&(!remote[p]||remote[p].sha!==F[p].s));
 let done=0,bytes=0;up.forEach(p=>bytes+=F[p].b.length);
 log('Envoi de '+up.length+' fichier(s) modifié(s) — '+(bytes/1e6).toFixed(1)+' Mo…');
 await pool(up,4,async p=>{const r=await gh(cfg,'POST','/git/blobs',{content:u64(F[p].b),encoding:'base64'});if(r.sha!==F[p].s)F[p].s=r.sha;if(++done%10===0||done===up.length)log('Envoi : '+done+' / '+up.length)});
 const tree=Object.keys(F).map(p=>({path:p,mode:'100644',type:'blob',sha:F[p].s}));
 Object.values(remote).forEach(x=>{if(!F[x.path]&&!PMANAGED(x.path))tree.push({path:x.path,mode:x.mode,type:'blob',sha:x.sha})});
 const del=Object.keys(remote).filter(p=>PMANAGED(p)&&!F[p]).length;
 const nt=await gh(cfg,'POST','/git/trees',{tree});
 const nc={};Object.keys(keys).forEach(p=>{if(F[p])nc[keys[p]]={p,s:F[p].s}});try{localStorage.setItem(PUBC,JSON.stringify(nc))}catch(e){}
 if(nt.sha===hc.tree.sha)return{same:true,rel};
 const cm=await gh(cfg,'POST','/git/commits',{message:'Mise à jour de la version légère — '+new Date().toLocaleString('fr-FR'),tree:nt.sha,parents:[head]});
 await gh(cfg,'PATCH','/git/refs/heads/'+br,{sha:cm.sha});
 return{sent:up.length,del,mb:bytes/1e6,rel}}

/* ---------- zip (sans compression) pour Netlify ou une sauvegarde ---------- */
function zipFiles(F){const crcT=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xEDB88320^c>>>1:c>>>1;crcT[n]=c>>>0}
 const crc=u=>{let c=0xFFFFFFFF;for(let i=0;i<u.length;i++)c=crcT[(c^u[i])&255]^c>>>8;return(c^0xFFFFFFFF)>>>0};
 const parts=[],cen=[];let off=0;const W=(a,v,o,n)=>{for(let i=0;i<n;i++)a[o+i]=v>>>(8*i)&255};
 Object.keys(F).sort().forEach(p=>{const name=PENC.encode('portail-leger/'+p),d=F[p].b,c=crc(d);
  const h=new Uint8Array(30+name.length);W(h,0x04034b50,0,4);W(h,20,4,2);W(h,0x0800,6,2);W(h,c,14,4);W(h,d.length,18,4);W(h,d.length,22,4);W(h,name.length,26,2);h.set(name,30);
  const z=new Uint8Array(46+name.length);W(z,0x02014b50,0,4);W(z,20,4,2);W(z,20,6,2);W(z,0x0800,8,2);W(z,c,16,4);W(z,d.length,20,4);W(z,d.length,24,4);W(z,name.length,28,2);W(z,off,42,4);z.set(name,46);
  parts.push(h,d);cen.push(z);off+=h.length+d.length});
 let cl=0;cen.forEach(z=>cl+=z.length);const end=new Uint8Array(22);W(end,0x06054b50,0,4);W(end,cen.length,8,2);W(end,cen.length,10,2);W(end,cl,12,4);W(end,off,16,4);
 return new Blob(parts.concat(cen,[end]),{type:'application/zip'})}

