/* ---------- STUDIO RI · lot 1 : brouillon, appliquer / abandonner, annuler / rétablir, aperçu étudiant ----------
   - E est le BROUILLON (ce que l'auteur modifie) ; il est gardé sous revInfas_edits_draft_v1 et survit au rechargement.
   - La configuration APPLIQUÉE (revInfas_edits_v1) n'est écrite que par « Appliquer » ; c'est la seule source
     des exports, du fichier lié et de la publication.
   - Annuler / rétablir : 50 étapes au plus, 25 Mo au plus, en mémoire ; les réglages rapides d'un même libellé
     (moins de 1,5 s) forment une seule étape.
   - Aperçu étudiant : lecture seule, palette de l'auteur, AUCUNE écriture de stockage (localStorage, sessionStorage,
     IndexedDB) ni dans le portail ni dans les applis ouvertes ; le stockage est en plus remis à l'identique en sortant. */
const DKEY=APPID+'_edits_draft_v1',ST_MAX=50,ST_OCTETS=25e6;
let APPLIED=null,APPLIED_SER='';const UNDO=[],REDO=[];let ST_CUR=null,ST_T=0,ST_L='',APERCU=null;
function stSer(e){const c=Object.assign({},e);delete c.base;delete c.rev;c.fontFiles=(e.fontFiles||[]).map(f=>f.name+':'+String(f.data||'').length);return JSON.stringify(c)}
function stAppliquee(){return APPLIED||E}
function stFixerAppliquee(a){APPLIED=a;APPLIED_SER=stSer(a);status()}
function stModifie(){return !!APPLIED&&stSer(E)!==APPLIED_SER}
function stAvecAppliquee(fn){const e0=E;E=stAppliquee();try{return fn()}catch(x){return null}finally{E=e0}}
function stBrouillonEcrire(){if(!APPLIED){/* avant l'initialisation du Studio : comportement d'origine */try{localStorage.setItem(EKEY,JSON.stringify(E))}catch(e){toast('⚠️ Stockage plein : exporte la version finale',4000)}return true}
 if(!stModifie()){try{localStorage.removeItem(DKEY)}catch(e){}return true}
 const d=clone(E),fa=(APPLIED&&APPLIED.fontFiles)||[];d.base=EMB.rev||0;
 d.fontFiles=(E.fontFiles||[]).map(f=>fa.some(g=>g.name===f.name&&g.data===f.data)?{name:f.name,ref:1}:f);
 try{localStorage.setItem(DKEY,JSON.stringify(d));return true}catch(e){toast('⚠️ Stockage plein : applique ou exporte tes modifications',4000);return false}}
function stEtat(){const c=Object.assign({},E);delete c.fontFiles;return{j:JSON.stringify(c),ff:(E.fontFiles||[]).slice()}}
function stPile(label,now){const s=stEtat();if(ST_CUR&&s.j===ST_CUR.j&&s.ff.length===ST_CUR.ff.length&&s.ff.every((f,i)=>f===ST_CUR.ff[i]))return;
 REDO.length=0;
 if(ST_CUR&&label===ST_L&&now-ST_T<1500){ST_CUR=s;ST_T=now;stBoutons();return}
 if(ST_CUR){UNDO.push(ST_CUR);let o=UNDO.reduce((n,x)=>n+x.j.length,0);while(UNDO.length>ST_MAX||(o>ST_OCTETS&&UNDO.length>1))o-=UNDO.shift().j.length}
 ST_CUR=s;ST_T=now;ST_L=label;stBoutons()}
function stFlush(){if(soonTimer){clearTimeout(soonTimer);soonTimer=null;commit(stSoonLabel)}}
function stCharger(s){E=normE(JSON.parse(s.j));E.fontFiles=s.ff.slice();E.base=EMB.rev||0;ST_L='';ST_T=0;stBrouillonEcrire();refresh(true);status()}
function stAnnuler(){stFlush();if(!UNDO.length)return false;REDO.push(ST_CUR);ST_CUR=UNDO.pop();stCharger(ST_CUR);toast('↶ Modification annulée');return true}
function stRetablir(){stFlush();if(!REDO.length)return false;UNDO.push(ST_CUR);ST_CUR=REDO.pop();stCharger(ST_CUR);toast('↷ Modification rétablie');return true}
function stAppliquer(){stFlush();if(!stModifie()){toast('Rien à appliquer : tout est déjà appliqué');return true}
 const a=clone(E);a.base=EMB.rev||0;
 try{localStorage.setItem(EKEY,JSON.stringify(a))}catch(e){toast('⚠️ Stockage plein : rien n’a été appliqué. Exporte la version finale.',5000);return false}
 stFixerAppliquee(a);try{localStorage.removeItem(DKEY)}catch(e){}scheduleFile();toast('✅ Modifications appliquées');sjNoter('applique','✅ Appliqué',clone(a));return true}
function stAbandonner(sansConfirmer){stFlush();if(!stModifie())return true;
 if(!sansConfirmer&&!confirm('Abandonner les modifications non appliquées ? (tu pourras encore les récupérer avec ↶ Annuler)'))return false;
 UNDO.push(ST_CUR);REDO.length=0;const a=clone(APPLIED);E=normE(a);E.fontFiles=(APPLIED.fontFiles||[]).slice();E.base=EMB.rev||0;
 ST_CUR=stEtat();ST_L='';try{localStorage.removeItem(DKEY)}catch(e){}refresh(true);status();toast('Modifications abandonnées : retour à la version appliquée');return true}
function stBoutons(){const d=(id,off)=>{const b=edq(id);if(b)b.disabled=!!off};d('#edUndo',!UNDO.length);d('#edRedo',!REDO.length);
 const m=stModifie();d('#edApply',!m);d('#edDiscard',!m);const a=edq('#edApply');if(a)a.classList.toggle('on',m)}
/* ---- aperçu étudiant ---- */
const ST_SP=Storage.prototype,ST_LS0={set:ST_SP.setItem,rem:ST_SP.removeItem,clr:ST_SP.clear},ST_IDB0={};
function stVerrou(on){if(on){ST_SP.setItem=function(k,v){if(APERCU){APERCU.bloque++;return}return ST_LS0.set.call(this,k,v)};
  ST_SP.removeItem=function(k){if(APERCU){APERCU.bloque++;return}return ST_LS0.rem.call(this,k)};
  ST_SP.clear=function(){if(APERCU){APERCU.bloque++;return}return ST_LS0.clr.call(this)};
  if(window.IDBObjectStore)['put','add','delete','clear'].forEach(m=>{const o=ST_IDB0[m]=IDBObjectStore.prototype[m];IDBObjectStore.prototype[m]=function(){const r=o.apply(this,arguments);if(APERCU){APERCU.bloque++;try{this.transaction.abort()}catch(e){}}return r}});
  if(window.IDBFactory){const o=ST_IDB0.open=IDBFactory.prototype.open;IDBFactory.prototype.open=function(){const r=o.apply(this,arguments);r.addEventListener('upgradeneeded',e=>{if(!APERCU)return;APERCU.bloque++;e.stopImmediatePropagation();try{r.transaction.abort()}catch(x){}});return r}}}
 else{ST_SP.setItem=ST_LS0.set;ST_SP.removeItem=ST_LS0.rem;ST_SP.clear=ST_LS0.clr;Object.keys(ST_IDB0).forEach(m=>{if(m==='open')IDBFactory.prototype.open=ST_IDB0[m];else IDBObjectStore.prototype[m]=ST_IDB0[m];delete ST_IDB0[m]})}}
const ST_VERROU_CADRE='<script>(function(){var n=function(){};try{var P=Storage.prototype;P.setItem=n;P.removeItem=n;P.clear=n}catch(e){}try{["put","add","delete","clear"].forEach(function(m){var o=IDBObjectStore.prototype[m];IDBObjectStore.prototype[m]=function(){var r=o.apply(this,arguments);try{this.transaction.abort()}catch(e){}return r}})}catch(e){}try{var F=IDBFactory.prototype,op=F.open;F.open=function(){var r=op.apply(this,arguments);r.addEventListener("upgradeneeded",function(e){e.stopImmediatePropagation();try{r.transaction.abort()}catch(x){}});return r}}catch(e){}window.__RI_APERCU=1})()<'+'/script>';
const _stAppSource=appSource;appSource=async function(m){const h=await _stAppSource.apply(this,arguments);if(!h||!APERCU)return h;return /<html[^>]*>/i.test(h)?h.replace(/<html[^>]*>/i,x=>x+ST_VERROU_CADRE):ST_VERROU_CADRE+h};
function stStockage(){const o={};for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);o[k]=localStorage.getItem(k)}return o}
function stApercu(on){if(on===undefined)on=!APERCU;
 if(on&&!APERCU){stFlush();closePanel();APERCU={ls:stStockage(),S:S,RO:RO,bloque:0,vue:{v:VIEW,pile:VSTACK.slice(),c:Object.assign({},ctx)}};stVerrou(true);
  if(S){S=clone(S);S.theme=null;S.night=null}RO=true;setEdit(false);document.body.classList.add('ed-apercu');
  document.body.insertAdjacentHTML('beforeend','<div id="edApercu"><span>👁 Aperçu étudiant · rien n’est enregistré</span>'+(innerWidth>=700?'<button id="edApercuTel">📱 Téléphone</button>':'')+'<button id="edApercuX">✕ Revenir à l’édition</button></div>');const tl=edq('#edApercuTel');if(tl)tl.onclick=stApercuTel;stInsFermer();
  edq('#edApercuX').onclick=()=>stApercu(false);applyLook();render();return true}
 if(!on&&APERCU){const A=APERCU;try{closeApp()}catch(e){}VIEW=A.vue.v;VSTACK=A.vue.pile;ctx=A.vue.c;APERCU=null;stVerrou(false);
  const now=stStockage();Object.keys(now).forEach(k=>{if(!(k in A.ls))localStorage.removeItem(k)});Object.keys(A.ls).forEach(k=>{if(now[k]!==A.ls[k])localStorage.setItem(k,A.ls[k])});
  S=A.S;RO=A.RO;const x=edq('#edApercu');if(x)x.remove();document.body.classList.remove('ed-apercu');setEdit(true);applyLook();render();
  window.__RI_APERCU_BLOQUE=A.bloque;return true}
 return false}
function studioInit(){APPLIED=clone(E);APPLIED.base=EMB.rev||0;APPLIED_SER=stSer(APPLIED);
 let d=null;try{d=JSON.parse(localStorage.getItem(DKEY)||'null')}catch(e){}
 if(d&&(d.base||0)>=(EMB.rev||0)){const fa=APPLIED.fontFiles||[];d.fontFiles=(d.fontFiles||[]).map(f=>f.ref?fa.find(g=>g.name===f.name):f).filter(f=>f&&f.data);
  E=normE(d);E.base=EMB.rev||0;if(stModifie()){refresh(true);toast('✏️ Brouillon non appliqué repris',3500)}else{try{localStorage.removeItem(DKEY)}catch(e){}}}
 else if(d)toast('Ancien brouillon ignoré : le fichier est plus récent',3500);
 ST_CUR=stEtat();if(location.hash==='#ri-apercu-tel')setTimeout(()=>stApercu(true),300);
 const sv=edq('#edSave');if(sv)sv.insertAdjacentHTML('beforebegin','<button id="edUndo" title="Annuler (Ctrl+Z)">↶</button><button id="edRedo" title="Rétablir (Ctrl+Y)">↷</button><button id="edPrev" title="Aperçu étudiant (rien n’est enregistré)">👁 Aperçu</button><button id="edApply" title="Appliquer : la version étudiants et les exports utiliseront ces réglages">✅ Appliquer</button><button id="edDiscard" title="Abandonner les modifications non appliquées">✖</button>');
 const on=(id,f)=>{const b=edq(id);if(b)b.onclick=f};on('#edUndo',stAnnuler);on('#edRedo',stRetablir);on('#edPrev',()=>stApercu(true));on('#edApply',stAppliquer);on('#edDiscard',()=>stAbandonner(false));
 document.addEventListener('keydown',e=>{if(!EDITMODE||APERCU||!(e.ctrlKey||e.metaKey))return;const t=e.target,saisie=t&&(t.isContentEditable||/^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName));if(saisie)return;
  const k=e.key.toLowerCase();if(k==='z'&&!e.shiftKey){e.preventDefault();stAnnuler()}else if(k==='y'||(k==='z'&&e.shiftKey)){e.preventDefault();stRetablir()}});
 status()}
function studioEtat(){return{modifie:stModifie(),annuler:UNDO.length,retablir:REDO.length,apercu:!!APERCU,bloque:APERCU?APERCU.bloque:(window.__RI_APERCU_BLOQUE||0),brouillon:(()=>{try{return localStorage.getItem(DKEY)!==null}catch(e){return null}})()}}

/* ---------- STUDIO RI · lot 2 : inspecteur, ciblage stable, glisser-déposer, taille et espacement, menu du bas ----------
   - Inspecteur unique (🧩 sur un élément, ⚙ sur une rubrique) : panneau bas sur téléphone, latéral sur ordinateur ;
     chaque réglage va dans le brouillon (lot 1) et s'annule avec ↶.
   - Ciblage stable : un style vise son groupe ou sa tuile par data-g / data-tile / data-grid au lieu de la position.
     Les anciens réglages (par position) s'appliquent toujours ; ils sont convertis quand l'auteur agit dessus.
   - Glisser-déposer : rubriques (poignée ⠿), groupes de cours, tuiles, boutons du menu. Souris : glisser ;
     toucher : appui long 0,5 s puis glisser, défilement automatique. Les flèches restent. */
const ST_ATTRS=['data-g','data-tile','data-grid','data-v'],ST_DECO='.ed-tb,.ed-tt,.rimatfil,.cved,.riedq,.riaddbar,.riacttb,.soonov,.rifil,.rimv';
const _stRiPath0=riPath;
function stPath(el,all){const sec=el.closest('section[data-inst]');const p=[];let x=el;
 while(x&&x!==sec&&x.nodeType===1&&x.id!=='app'){let s=x.tagName.toLowerCase();const cl=[].slice.call(x.classList).filter(c=>!/^(on|active|open|sel|ri|soon|lic|cv|acthid|hide|st-)/.test(c)).slice(0,2);if(cl.length)s+='.'+cl.map(CSS.escape).join('.');
  const at=ST_ATTRS.find(a=>x.hasAttribute(a));
  if(at)s+='['+at+'="'+String(x.getAttribute(at)).replace(/["\\]/g,'\\$&')+'"]';
  else{let i=1,y=x;while(y=y.previousElementSibling)if(y.tagName===x.tagName&&!y.matches(ST_DECO))i++;s+=':nth-of-type('+i+')'}p.unshift(s);x=x.parentElement}
 const q=v=>String(v).replace(/["\\]/g,'\\$&'),base='body[data-view="'+q(VIEW)+'"]'+(!all&&ctx&&ctx.id?'[data-ctx="'+q(ctx.id)+'"]':'')+' '+(sec?'section[data-inst="'+q(sec.dataset.inst)+'"]':'#app');return base+(p.length?'>'+p.join('>'):'')}
riPath=stPath;
/* affichage des réglages dans l'éditeur : les positions (« :nth-of-type(n) ») sont comptées sans les barres du Studio
   (comme stPath), alors qu'en mode édition ces barres sont présentes dans la page. Seulement pendant l'édition, la feuille
   #ri-sty est réécrite en « :nth-child(n of balise:not(barres)) » ; les réglages enregistrés et la version étudiants
   ne changent pas. Sans prise en charge de cette écriture par le navigateur : comportement d'origine. */
const stNthOf=(()=>{try{return CSS.supports('selector(:nth-child(1 of a))')}catch(e){return false}})();
function stSelEdition(css){return css.replace(/(^|[\s>+~}])([a-z][a-z0-9-]*)((?:\.(?:\\.|[^\s>+~:.\[{,])+|\[[^\]]*\])*):nth-of-type\((\d+)\)/g,
 (m,a,tag,rest,n)=>a+tag+rest+':nth-child('+n+' of '+tag+':not('+ST_DECO+'))')}
const stRiStyCss0=riStyCss;
riStyCss=function(){stRiStyCss0.apply(this,arguments);if(!stNthOf||!edOn()||APERCU)return;const st=document.getElementById('ri-sty');if(!st)return;
 const out=stSelEdition(st.textContent);if(st.textContent!==out)st.textContent=out};
/* convertit les anciens réglages (par position) qui visent ces éléments ou leur contenu, avant un déplacement */
function stRemap(nodes){const M=E.content&&E.content.riSty;if(!M)return 0;let n=0;
 nodes.forEach(nd=>[true,false].forEach(all=>{const lp=_stRiPath0(nd,all),sp=stPath(nd,all);if(lp===sp)return;
  Object.keys(M).forEach(k=>{if(k===lp||k.startsWith(lp+'>')){const nk=sp+k.slice(lp.length);if(!(nk in M))M[nk]=M[k];delete M[k];n++}})}));return n}
/* range des identifiants dans une liste complète en gardant la place des éléments non affichés */
function stRanger(full,cle,ids){const pos=[];full.forEach((o,i)=>{if(ids.includes(cle(o)))pos.push(i)});const par={};full.forEach(o=>par[cle(o)]=o);
 const out=full.slice();ids.filter(id=>par[id]).forEach((id,k)=>{if(pos[k]!=null)out[pos[k]]=par[id]});return out}

/* ---- inspecteur ---- */
let ST_INS=null;
const ST_CRANS=['Aucune','Très petite','Petite','Moyenne','Grande'];
function stInsFermer(){const o=edq('#stIns');if(o)o.remove();ST_INS=null;$$('.st-cible').forEach(x=>x.classList.remove('st-cible'))}
