/* ---- glisser-déposer (souris et toucher) ---- */
let ST_DND=null;
function stTriable(item,cfg){const h=cfg.poignee||item;if(h.__stT)return;h.__stT=1;h.classList.add('st-tri');
 h.addEventListener('pointerdown',e=>{if(e.button!==0||APERCU||ST_DND||(typeof RIPICK!=='undefined'&&RIPICK))return;if(e.target.closest('input,textarea,select,.ed-tt,.ed-tb button'))return;
  const toucher=e.pointerType!=='mouse',x0=e.clientX,y0=e.clientY;let tm=null;
  const stop=()=>{clearTimeout(tm);document.removeEventListener('pointermove',mv);document.removeEventListener('pointerup',stop);document.removeEventListener('pointercancel',stop)};
  const mv=ev=>{const dd=Math.hypot(ev.clientX-x0,ev.clientY-y0);if(toucher){if(dd>8)stop()}else if(dd>6){stop();stDndDebut(item,cfg);stDndBouge(ev)}};
  if(toucher)tm=setTimeout(()=>{stop();stDndDebut(item,cfg);ST_DND.x=x0;ST_DND.y=y0},500);
  document.addEventListener('pointermove',mv);document.addEventListener('pointerup',stop);document.addEventListener('pointercancel',stop)});
 h.addEventListener('contextmenu',e=>{if(ST_DND||e.pointerType!=='mouse')e.preventDefault()})}
function stTm(e){if(ST_DND)e.preventDefault()}
function stDndDebut(item,cfg){try{if(cfg.avant)cfg.avant()}catch(e){}ST_DND={item,cfg,x:0,y:0,ids0:cfg.liste().map(cfg.cle).join('|')};
 item.classList.add('st-drag');document.body.classList.add('st-dnd');try{navigator.vibrate&&navigator.vibrate(15)}catch(e){}
 document.addEventListener('pointermove',stDndBouge);document.addEventListener('pointerup',stDndFin);document.addEventListener('pointercancel',stDndAnnule);document.addEventListener('touchmove',stTm,{passive:false});
 const tour=()=>{if(!ST_DND)return;const m=70,y=ST_DND.y;let v=0;if(y&&y<m)v=-Math.ceil((m-y)/5);else if(y>innerHeight-m)v=Math.ceil((y-(innerHeight-m))/5);if(v){scrollBy(0,v);stPlacer()}ST_DND.raf=requestAnimationFrame(tour)};ST_DND.raf=requestAnimationFrame(tour)}
function stDndBouge(e){if(!ST_DND)return;ST_DND.x=e.clientX;ST_DND.y=e.clientY;stPlacer()}
function stPlacer(){const D=ST_DND,it=D.item,L=D.cfg.liste().filter(x=>x!==it);let best=null,bd=1e9;
 L.forEach(o=>{const r=o.getBoundingClientRect(),dd=Math.hypot(D.x-(r.left+r.width/2),D.y-(r.top+r.height/2));if(dd<bd){bd=dd;best=o}});if(!best)return;
 const r=best.getBoundingClientRect(),apres=D.cfg.grille?(D.y>r.bottom||(D.y>=r.top&&D.x>r.left+r.width/2)):D.y>r.top+r.height/2;
 const ref=apres?best.nextElementSibling:best;if(ref===it||(apres&&best.nextElementSibling===it)||(!apres&&best.previousElementSibling===it&&false))return;best.parentNode.insertBefore(it,ref)}
function stDndNettoie(){const D=ST_DND;cancelAnimationFrame(D.raf);document.removeEventListener('pointermove',stDndBouge);document.removeEventListener('pointerup',stDndFin);document.removeEventListener('pointercancel',stDndAnnule);document.removeEventListener('touchmove',stTm);
 D.item.classList.remove('st-drag');document.body.classList.remove('st-dnd');ST_DND=null;
 const bloque=ev=>{ev.preventDefault();ev.stopPropagation();ev.stopImmediatePropagation()};document.addEventListener('click',bloque,true);setTimeout(()=>document.removeEventListener('click',bloque,true),350);return D}
function stDndFin(){const D=stDndNettoie(),ids=D.cfg.liste().map(D.cfg.cle);if(ids.join('|')!==D.ids0)D.cfg.fin(ids);else render()}
function stDndAnnule(){stDndNettoie();render()}

